void unregister_ppp_channel(struct ppp_channel *chan) {
    if (!chan)
        return;

    /* Set PPP pointer to NULL */
    chan->ppp = NULL;

    /* Acquire write lock to ensure no ongoing operations */
    write_lock(&chan->lock);

    /* Disconnect the channel */
    ppp_disconnect(chan);

    /* Remove from the list of channels */
    list_del(&chan->list);

    /* Decrement the reference count of the file structure */
    if (chan->file) {
        if (!atomic_dec_and_test(&chan->file->f_count))
            wait_for_completion(&chan->file->comp);
        else
            kfree(chan->file);
    }

    /* Destroy the channel */
    kfree(chan);
    wake_up_all(&chan->wait);
}

void unregister_ppp_channel(struct ppp_channel *chan) {
    if (chan == NULL || chan->file == NULL)
        return;

    write_lock(&chan->lock);
    chan->ppp = NULL;

    ppp_disconnect(chan);
    list_del(&chan->list);
    if (chan->file) {
        if (!atomic_dec_and_test(&chan->file->f_count))
            wake_up_all(&chan->file->wait);
    }

    if (atomic_read(&chan->f_count) == 0)
        kfree(chan);
}

